+#include "tui/app.hpp"
+
+#include <string_view>
+#include <vector>
+
+#include "searchengine/searchengine.hpp"
+
+namespace {}  // namespace
+
+void AppState::switch_mode(std::string_view mode_name) {
+    if (mode_name == "or") {
+        this->mode = SearchMode::Or;
+    } else if (mode_name == "and") {
+        this->mode = SearchMode::And;
+    } else if (mode_name == "phrase") {
+        this->mode = SearchMode::Phrase;
+    } else if (mode_name == "not") {
+        this->mode = SearchMode::Not;
+    } else if (mode_name == "near") {
+        this->mode = SearchMode::Near;
+    }
+}
+
+std::string mode_to_str(const SearchMode& mode) {
+    switch (mode) {
+        case SearchMode::Or:
+            return "or";
+        case SearchMode::And:
+            return "and";
+        case SearchMode::Not:
+            return "not";
+        case SearchMode::Phrase:
+            return "phrase";
+        case SearchMode::Near:
+            return "near";
+    }
+}
+
+std::vector<std::string> AppState::get_files() {
+    std::vector<std::string> files;
+    for (std::string& path : this->searchengine.list_book_files(this->data_path).value()) {
+        if (!this->searchengine.is_loaded(path)) {
+            files.emplace_back(std::move(path));
+        }
+    }
+    return files;
+}
+
+SearchResult AppState::get_context(int idx) {
+    return this->searchengine.get_context(this->search_res[idx]);
+}

