64: ftxui::Element compare_pane(const std::vector<CompareMetric>& metrics) {
65:     using namespace ftxui;
66: 
67:     Elements rows{text("Algorithm        Count      Comparisons      Time(ms)") | bold,
68:         separator()};
69:     for (const CompareMetric& metric : metrics) {
70:         rows.push_back(text(std::format("{:<14} {:>8} {:>16} {:>13}",
71:             metric.name,
72:             metric.match_count,
73:             metric.compare_count,
74:             metric.use_time_ms)));
75:     }
76:     return vbox(std::move(rows)) | frame | flex;
77: }
