79: std::vector<CompareMetric> make_compare_metrics(std::string_view source, std::string_view target) {
80:     const auto results = test_algos(source, target, brute_force, kmp, boyer_moore, rabin_karp);
81:     return {
82:         CompareMetric{.name = "brute_force",
83:             .match_count = results[0].index.size(),
84:             .compare_count = results[0].compare_count,
85:             .use_time_ms = results[0].use_time.count()},
86:         CompareMetric{.name = "kmp",
87:             .match_count = results[1].index.size(),
88:             .compare_count = results[1].compare_count,
89:             .use_time_ms = results[1].use_time.count()},
90:         CompareMetric{.name = "boyer_moore",
91:             .match_count = results[2].index.size(),
92:             .compare_count = results[2].compare_count,
93:             .use_time_ms = results[2].use_time.count()},
94:         CompareMetric{.name = "rabin_karp",
95:             .match_count = results[3].index.size(),
96:             .compare_count = results[3].compare_count,
97:             .use_time_ms = results[3].use_time.count()},
98:     };
99: }
