161:     auto mode_button = Button("Mode", mode_fn);
162:     auto mode_modal = Renderer(change_buttons, [&] {
163:         return vbox({text("Choose Mode") | center, separator(), change_buttons->Render()}) | border;
164:     }) | CatchEvent([&mode_con](Event event) {
165:         if (event == Event::Escape) {
